use moloch_replay::{session::Session,Side};
use serde_json::{json,Value};
use sha2::{Digest,Sha256};
use std::{fs,path::PathBuf};

const BASE:i64=1_792_054_800_000;
fn iso(t:i64)->String{chrono::DateTime::from_timestamp_millis(BASE+t).unwrap().to_rfc3339_opts(chrono::SecondsFormat::Millis,true)}
fn hash(v:&Value)->String{format!("{:x}",Sha256::digest(serde_json::to_vec(v).unwrap()))}
struct F{root:PathBuf,bank:Option<Session>,policy:Value,seed:Value,side:&'static str,book_sha:String}
impl Drop for F{fn drop(&mut self){self.bank.take();let _=fs::remove_dir_all(&self.root);}}
impl F{
 fn new(side:&'static str,bps:u64,per:&str,managed:bool)->Self{
  let root=std::env::temp_dir().join(format!("reviewed-passive-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));fs::create_dir(&root).unwrap();
  let policy=json!({"initialCash":"1000.000000","maximumCommitted":"800.000000","maximumMarketCost":"100.000000","maximumMarkets":3,"quantity":5,"inventoryExitMode":"fixedGain","maximumInventoryAgeMs":60000,"inventoryMinimumGain":"0.005000","inventoryAgeClock":"execution","feeBps":bps,"feePerShare":per,"entryStopAt":iso(300000)});
  let seed=json!({"runId":"passive-fixture","availableCash":"1000.000000","accountSnapshotHash":"a".repeat(64),"observedAt":iso(0)});
  let bank=Session::open_live(&root.join("bank"),&policy,&seed).unwrap();let mut f=Self{root,bank:Some(bank),policy,seed,side,book_sha:String::new()};
  f.put(&json!({"type":"actual_position_adoption","source":"official_sig_api_v1","authority":"human_moloch_inherited_management_20261015","complete":true,"receiptHash":"a".repeat(64),"tournamentId":"cup","receivedAt":iso(0),"requestStartedAt":iso(0),"openingCost":"3.450000","effectiveMaximumMarkets":4,"positions":[{"marketId":"201","exchangeId":"101","quantity":if side=="YES"{5}else{-5},"lotPrincipal":"3.450000","reportedCostBasis":"3.450000","reportedMinusLotPrincipal":"0.000000","basisClassification":"exact","lots":[{"lotId":"901","quantity":5,"side":side,"entryPrice":"0.690000","openedAt":iso(-60000)}]}]})).unwrap();
  if managed{f.mode(true,0);}
  f.book(1000,"0.200000","0.300000",1);
  // Fixture cleanup is genuine never-bound retirement, not a canceled physical
  // order. Avoid native immediate re-planning during this explicit cleanup.
  for q in f.b().engine().order_records().into_iter().filter(|q|q["retired"]==false){f.put(&json!({"type":"unsubmitted_intent_retired","source":"moloch_live_dispatcher","orderId":q["id"],"confirmedNetworkAttempts":0,"receiptHash":"c".repeat(64),"deferPlanningForPackage":true,"receivedAt":iso(1001)})).unwrap();}
  f
 }
 fn b(&self)->&Session{self.bank.as_ref().unwrap()}
 fn put(&mut self,e:&Value)->Result<bool,Box<dyn std::error::Error>>{let seq=self.b().last_source_sequence("fixture")+1;self.bank.as_mut().unwrap().accept("fixture",seq,e)}
 fn bound(&self,kind:&str,t:i64)->Value{json!({"type":kind,"source":"moloch_live_dispatcher","receivedAt":iso(t),"processedAt":iso(t),"bankScope":{"runId":"passive-fixture","bankManifestHash":self.b().manifest_hash(),"tournamentId":"cup"},"bankHead":self.b().durable_head(),"expectedReportSha256":hash(&self.b().engine().report().unwrap())})}
 fn mode(&mut self,on:bool,t:i64){let mut e=self.bound("managed_inventory_planning_v1",t);e["managedExchangeIds"]=if on{json!(["101"])}else{json!([])};e["approvedReviewSetSha256"]=json!("b".repeat(64));e["generationSha256"]=json!("0".repeat(64));e["controlSha256"]=json!("c".repeat(64));e["expectedPreviousModeSha256"]=self.b().engine().managed_inventory_planning_record().map_or(Value::Null,|r|r["sha256"].clone());self.put(&e).unwrap();}
 fn book(&mut self,t:i64,bid:&str,ask:&str,depth:u64){let seq=self.b().last_source_sequence("books")+1;self.bank.as_mut().unwrap().accept("books",seq,&json!({"type":"book","receivedAt":iso(t),"book":{"marketId":"201","exchangeId":"101","tournamentId":"cup","sequence":seq.to_string(),"requestStartedAt":iso(t),"sourceAt":iso(t),"receivedAt":iso(t),"bids":[{"price":bid,"quantity":depth}],"asks":[{"price":ask,"quantity":depth}]}})).unwrap();self.book_sha=hash(&self.b().engine().live_package_books()[0]);}
 fn event(&self,t:i64,n:u64,limit:&str,value:&str)->Value{
  let mut e=self.bound("reviewed_inventory_exit_reserved_v1",t);let adoption=self.b().committed_source_hash("fixture",1).unwrap();
  for(k,v)in json!({"exchangeId":"101","marketId":"201","side":self.side,"quantity":n,"limitPrice":limit,"expectedPayout":value,"reason":"refreshed_value_exit","reviewCurrentUntilMs":BASE+100000,"holdingDeadlineMs":BASE+100000,"expiresAt":iso(60000),"revoked":false,"originSha256":"a".repeat(64),"reviewSha256":"b".repeat(64),"bookSha256":self.book_sha,"expectedPositionSha256":hash(&self.b().engine().wallet.positions()["101"]),"adoptionReceiptHash":"a".repeat(64),"adoptionRef":{"id":"fixture","sequence":1,"sha256":adoption},"executionMode":"passiveValueLimit","maximumPassiveQuantity":5,"modelSha256":"d".repeat(64),"sourceSha256":"e".repeat(64)}).as_object().unwrap(){e[k]=v.clone();}e
 }
 fn q(&self)->Value{self.b().engine().order_records().into_iter().find(|q|q["reviewedInventoryExit"]["executionMode"]=="passiveValueLimit").unwrap()}
 fn actual(&self,kind:&str,q:&Value,t:i64)->Value{json!({"type":kind,"source":"official_sig_api_v1","receiptHash":"f".repeat(64),"orderId":q["id"],"actualOrderId":"10001","marketId":"201","exchangeId":"101","side":self.side,"action":"sell","quantity":q["quantity"],"price":q["price"],"receivedAt":iso(t)})}
 fn deny(&mut self,e:&Value){let head=self.b().durable_head();let report=self.b().engine().report().unwrap();let orders=self.b().engine().order_records();assert!(self.put(e).is_err(),"unexpected accepted {e}");assert_eq!(self.b().durable_head(),head);assert_eq!(self.b().engine().report().unwrap(),report);assert_eq!(self.b().engine().order_records(),orders);}
}

#[test]fn yes_and_no_rest_without_invented_depth_or_cash_and_preserve_metadata(){for side in ["YES","NO"]{let mut f=F::new(side,0,"0.000000",true);let before=f.b().engine().report().unwrap();let e=f.event(4000,5,"0.815000","0.810001");f.put(&e).unwrap();let q=f.q();assert_eq!(q["quantity"],5);assert_eq!(q["price"],"0.815000");assert_eq!(q["reviewedInventoryExit"]["minimumNetValue"],"0.810001");assert_eq!(q["reviewedInventoryExit"]["maximumPassiveQuantity"],5);assert_eq!(q["reviewedInventoryExit"]["modelSha256"],"d".repeat(64));assert_eq!(q["reviewedInventoryExit"]["sourceSha256"],"e".repeat(64));assert!(q.get("executionStyle").is_none());let r=f.b().engine().report().unwrap();for k in ["cash","ownedCost","realized","fills"]{assert_eq!(r[k],before[k]);}assert_eq!(r["reservedCash"],before["reservedCash"]);assert_eq!(f.b().engine().wallet.quantity("101",if side=="YES"{Side::Yes}else{Side::No}),5);}}
#[test]fn value_limit_may_execute_above_floor_without_full_depth(){let mut f=F::new("YES",0,"0.000000",true);f.book(3000,"0.850000","0.855000",1);let e=f.event(4000,5,"0.815000","0.810000");f.put(&e).unwrap();assert_eq!(f.q()["quantity"],5);assert!(f.b().engine().fills().is_empty());}
#[test]fn fee_ceiling_and_tick_rounding_protect_each_partial_unit(){let mut f=F::new("YES",100,"0.002000",true);f.deny(&f.event(4000,5,"0.805000","0.800000"));f.deny(&f.event(4000,5,"0.814999","0.800000"));let e=f.event(4000,5,"0.815000","0.800000");f.put(&e).unwrap();assert_eq!(f.q()["reviewedInventoryExit"]["minimumNetValue"],"0.800000");}
#[test]fn fair_value_is_not_fifo_profit_and_no_second_margin_is_added(){let mut f=F::new("YES",0,"0.000000",true);let e=f.event(4000,5,"0.600000","0.600000");f.put(&e).unwrap();assert_eq!(f.q()["price"],"0.600000");assert_eq!(f.b().engine().report().unwrap()["realized"],"0.000000");}
#[test]fn default_executable_depth_and_metadata_stay_exact(){let mut a=F::new("YES",0,"0.000000",true);let mut b=F::new("YES",0,"0.000000",true);let mut e=a.event(4000,1,"0.200000","0.200000");for k in ["executionMode","maximumPassiveQuantity","modelSha256","sourceSha256"]{e.as_object_mut().unwrap().remove(k);}a.put(&e).unwrap();let mut explicit=b.event(4000,1,"0.200000","0.200000");for k in ["maximumPassiveQuantity","modelSha256","sourceSha256"]{explicit.as_object_mut().unwrap().remove(k);}explicit["executionMode"]=json!("executableDepth");b.put(&explicit).unwrap();assert_eq!(a.b().engine().report().unwrap(),b.b().engine().report().unwrap());assert_eq!(a.b().engine().order_records(),b.b().engine().order_records());let record=&a.b().engine().order_records()[0]["reviewedInventoryExit"];assert!(record.get("executionMode").is_none());assert!(record.get("minimumNetValue").is_none());let mut c=F::new("YES",0,"0.000000",true);let mut e=c.event(4000,5,"0.815000","0.810000");e.as_object_mut().unwrap().remove("executionMode");c.deny(&e);}
#[test]fn malformed_unknown_cohort_revocation_caps_and_expiry_fail_atomically(){for case in ["unknown","null","cohort","revoked","proof","zero_cap","over_cap","over_owned","review_expiry","activation_expiry"]{let mut f=F::new("YES",0,"0.000000",true);let mut e=f.event(4000,5,"0.815000","0.810000");match case{"unknown"=>e["executionMode"]=json!("arbitrary"),"null"=>e["executionMode"]=Value::Null,"cohort"=>e["type"]=json!("reviewed_cohort_exit_reserved_v1"),"revoked"=>{e["reason"]=json!("reviewed_source_revocation");e["revoked"]=json!(true)},"proof"=>e["sourceSha256"]=json!("untrusted"),"zero_cap"=>e["maximumPassiveQuantity"]=json!(0),"over_cap"=>e["maximumPassiveQuantity"]=json!(4),"over_owned"=>e["quantity"]=json!(6),"review_expiry"=>e["reviewCurrentUntilMs"]=json!(BASE+59000),_=>e["expiresAt"]=json!(iso(7000))}f.deny(&e);}}
#[test]fn source_origin_position_and_head_changes_cannot_rebind(){for case in ["book","head","adoption","position","market","stale","gap"]{let mut f=F::new("NO",0,"0.000000",true);if case=="gap"{f.put(&json!({"type":"gap","exchangeId":"101","receivedAt":iso(3000)})).unwrap();}let mut e=f.event(if case=="stale"{12000}else{4000},5,"0.815000","0.810000");match case{"book"=>e["bookSha256"]=json!("0".repeat(64)),"head"=>e["bankHead"]["previous"]=json!("0".repeat(64)),"adoption"=>e["adoptionRef"]["sha256"]=json!("0".repeat(64)),"position"=>e["expectedPositionSha256"]=json!("0".repeat(64)),"market"=>e["marketId"]=json!("202"),_=>{}}f.deny(&e);}}
#[test]fn planning_exclusion_is_required_and_one_order_pledges_owned_units(){let mut f=F::new("YES",0,"0.000000",false);f.deny(&f.event(4000,5,"0.815000","0.810000"));f.mode(true,4000);let e=f.event(4000,5,"0.815000","0.810000");f.put(&e).unwrap();f.deny(&f.event(7000,1,"0.815000","0.810000"));let q=f.q();f.put(&f.actual("actual_order_ack",&q,7100)).unwrap();f.deny(&f.event(7200,1,"0.815000","0.810000"));let before=f.b().engine().order_records();f.book(8000,"0.250000","0.300000",1);assert_eq!(f.b().engine().order_records(),before);}
#[test]fn partial_fill_original_idempotency_cancel_and_restart_preserve_fifo_and_remainder(){let mut f=F::new("NO",0,"0.000000",true);let e=f.event(4000,5,"0.815000","0.810000");f.put(&e).unwrap();let q=f.q();let cash=f.b().engine().report().unwrap()["cash"].clone();f.put(&f.actual("actual_order_ack",&q,7100)).unwrap();assert_eq!(f.b().engine().report().unwrap()["cash"],cash);let mut fill=f.actual("actual_fill",&q,8001);fill["fillId"]=json!("20001");fill["quantity"]=json!(2);fill["executedAt"]=json!(iso(8000));fill["fee"]=json!("0.000000");f.put(&fill).unwrap();let seq=f.b().last_source_sequence("fixture");assert!(!f.bank.as_mut().unwrap().accept("fixture",seq,&fill).unwrap());assert_eq!(f.b().engine().wallet.quantity("101",Side::No),3);assert_eq!(f.b().engine().report().unwrap()["realized"],"0.250000");assert_eq!(f.b().engine().fills().len(),1);f.deny(&f.event(8100,3,"0.815000","0.810000"));let mut end=f.actual("actual_order_terminal",&q,9000);end["filledQuantity"]=json!(2);end["fillsComplete"]=json!(true);end["status"]=json!("canceled");f.put(&end).unwrap();let report=f.b().engine().report().unwrap();let orders=f.b().engine().order_records();let head=f.b().durable_head();f.bank.take();f.bank=Some(Session::open_live(&f.root.join("bank"),&f.policy,&f.seed).unwrap());assert_eq!(f.b().engine().report().unwrap(),report);assert_eq!(f.b().engine().order_records(),orders);assert_eq!(f.b().durable_head(),head);f.book(10000,"0.250000","0.300000",1);let e=f.event(11000,3,"0.815000","0.810000");f.put(&e).unwrap();assert_eq!(f.b().engine().wallet.quantity("101",Side::No),3);assert_eq!(f.b().engine().fills().len(),1);}
